import pandas as pd
import seaborn as sns
import numpy as np
import ast

def task_func(csv_file):
    import matplotlib.pyplot as plt

    df = pd.read_csv(csv_file)

    # Normalize expected column names if needed.
    rename_map = {}
    if "email" not in df.columns:
        if len(df.columns) >= 1:
            rename_map[df.columns[0]] = "email"
    if "list" not in df.columns:
        if len(df.columns) >= 2:
            rename_map[df.columns[1]] = "list"

    if rename_map:
        df = df.rename(columns=rename_map)

    if "email" not in df.columns or "list" not in df.columns:
        raise ValueError("CSV file must contain columns for email data and list data.")

    def parse_list(value):
        if isinstance(value, list):
            return value
        if isinstance(value, tuple):
            return list(value)
        if isinstance(value, np.ndarray):
            return value.tolist()
        if pd.isna(value):
            return []
        if isinstance(value, str):
            text = value.strip()
            if not text:
                return []
            try:
                parsed = ast.literal_eval(text)
            except (ValueError, SyntaxError):
                if "," in text:
                    parsed = [item.strip() for item in text.split(",") if item.strip() != ""]
                else:
                    return [text]
            if isinstance(parsed, list):
                return parsed
            if isinstance(parsed, tuple):
                return list(parsed)
            if isinstance(parsed, np.ndarray):
                return parsed.tolist()
            return [parsed]
        return [value]

    def compute_stats(values):
        numeric = pd.to_numeric(pd.Series(values), errors="coerce").dropna().to_numpy(dtype=float)
        if numeric.size == 0:
            return 0.0, np.nan, np.nan
        return float(numeric.sum()), float(numeric.mean()), float(numeric.std(ddof=0))

    parsed_lists = df["list"].apply(parse_list)
    stats = parsed_lists.apply(lambda x: pd.Series(compute_stats(x), index=["sum", "mean", "std"]))

    result_df = pd.DataFrame(
        {
            "email": df["email"],
            "list": parsed_lists,
            "sum": stats["sum"],
            "mean": stats["mean"],
            "std": stats["std"],
        }
    )

    fig, ax = plt.subplots()
    mean_values = result_df["mean"].dropna()
    sns.histplot(mean_values, ax=ax)
    ax.set_xlabel("Mean")
    ax.set_ylabel("Count")
    ax.set_title("Histogram of Mean Values")

    return result_df, ax

