import pandas as pd
import numpy as np
import itertools
from datetime import datetime, timedelta
import seaborn as sns

def task_func(df, fruits=None, days=None, seed=None, sales_lower_bound=1, sales_upper_bound=50):
    if not isinstance(df, pd.DataFrame):
        raise TypeError("'df' must be a pandas DataFrame")
    if not df.empty:
        raise ValueError("'df' must be empty")
    if sales_lower_bound >= sales_upper_bound:
        raise ValueError("'sales_lower_bound' must be less than 'sales_upper_bound'")

    if fruits is None:
        fruits = ["apple", "banana", "orange"]
    elif isinstance(fruits, str):
        fruits = [fruits]
    else:
        fruits = list(fruits)

    if not fruits:
        raise ValueError("'fruits' must contain at least one item")

    if days is None:
        days = 7
    elif not isinstance(days, (int, np.integer)):
        raise TypeError("'days' must be an integer")

    days = int(days)
    if days <= 0:
        raise ValueError("'days' must be a positive integer")

    rng = np.random.default_rng(seed)
    start_date = datetime.now().date()

    rows = []
    for day_offset, fruit in itertools.product(range(days), fruits):
        rows.append(
            {
                "date": start_date + timedelta(days=day_offset),
                "fruit": fruit,
                "sales": int(rng.integers(sales_lower_bound, sales_upper_bound)),
            }
        )

    generated_df = pd.DataFrame(rows)
    updated_df = pd.concat([df, generated_df], ignore_index=True)
    plot = sns.catplot(data=updated_df, x="fruit", y="sales", kind="box", order=fruits)

    return updated_df, plot

