import re
import json
import requests

API_ENDPOINT = "https://example.com/api"
_URL_PATTERN = re.compile(r"(?:https?://|www\.)[^\s<>'\"()]+")
_TRAILING_PUNCTUATION = '.,;:!?)]}\'"'


def _extract_first_url(text):
    if text is None:
        return None

    if not isinstance(text, str):
        text = str(text)

    match = _URL_PATTERN.search(text)
    if not match:
        return None

    url = match.group(0).rstrip(_TRAILING_PUNCTUATION)
    if url.startswith("www."):
        url = "http://" + url

    return url or None


def task_func(myString, token):
    url = _extract_first_url(myString)
    if not url:
        return {"error": "No URL found in the input string."}

    headers = {}
    if token is not None:
        token_str = str(token)
        headers["Authorization"] = (
            token_str if token_str.lower().startswith("bearer ") else f"Bearer {token_str}"
        )

    payload = {"url": url}

    try:
        response = requests.post(API_ENDPOINT, json=payload, headers=headers)
        try:
            data = response.json()
        except (ValueError, json.JSONDecodeError):
            return {"response": getattr(response, "text", "")}

        return data if isinstance(data, dict) else {"response": data}
    except requests.RequestException as exc:
        return {"error": str(exc)}

