import numpy as np
import random


def task_func(MIN_WORDS, MAX_WORDS, WORDS_POOL):
    try:
        min_words = int(MIN_WORDS)
        max_words = int(MAX_WORDS)
    except Exception as exc:
        raise ValueError("MIN_WORDS and MAX_WORDS must be integers") from exc

    if min_words < 0 or max_words < 0:
        raise ValueError("MIN_WORDS and MAX_WORDS must be non-negative")

    if min_words > max_words:
        min_words, max_words = max_words, min_words

    if isinstance(WORDS_POOL, str):
        pool = WORDS_POOL.split()
    else:
        pool = list(WORDS_POOL)

    if not pool:
        if min_words == 0:
            return ""
        raise ValueError("WORDS_POOL must contain at least one word")

    length = random.randint(min_words, max_words)

    if length == 0:
        return ""

    half = length // 2
    left_side = [random.choice(pool) for _ in range(half)]
    middle = [random.choice(pool)] if length % 2 else []
    sentence_words = left_side + middle + left_side[::-1]

    return " ".join(sentence_words)

