    Scan csv_dir for CSV files, find the first row index whose first cell equals target_value,
    and optionally move matched files to processed_dir.

    Returns:
        dict: {filename: row_index}
    """
    result = {}

    if not os.path.isdir(csv_dir):
        return result

    try:
        csv_files = sorted(
            name for name in os.listdir(csv_dir)
            if name.lower().endswith('.csv') and os.path.isfile(os.path.join(csv_dir, name))
