        for row in cursor.execute(
            "SELECT name FROM sqlite_master "
            "WHERE type='table' AND name NOT LIKE 'sqlite_%' "
            "ORDER BY CASE WHEN name='users' THEN 0 WHEN name='user' THEN 1 ELSE 2 END, name"
        ).fetchall()
    ]

    target_table = None
    target_info = None
    for table in table_names:
        info = cursor.execute(f"PRAGMA table_info({quote_identifier(table)})").fetchall()
        columns = [col[1] for col in info]
        if "password" in columns:
            target_table = table
            target_info = info
            break

    if target_table is None:
        return 0

    pk_columns = [col[1] for col in target_info if col[5]]
    table_q = quote_identifier(target_table)
    password_q = quote_identifier("password")
    updated = 0

    if pk_columns:
        pk_q = [quote_identifier(col) for col in pk_columns]
        select_cols = ", ".join(pk_q + [password_q])
        where_clause = " AND ".join(f"{col} = ?" for col in pk_q)
        rows = cursor.execute(
            f"SELECT {select_cols} FROM {table_q} WHERE {password_q} IS NOT NULL"
        ).fetchall()
        update_sql = f"UPDATE {table_q} SET {password_q} = ? WHERE {where_clause}"

        for row in rows:
