import requests
import pandas as pd


def task_func(url: str) -> pd.DataFrame:
    """
    Fetch JSON data from a URL and convert it into a pandas DataFrame.

    The function:
    - Uses a 5 second timeout for the request.
    - Raises SystemError for network-related issues or unsuccessful HTTP status codes.
    - Raises ValueError if the response body is not valid JSON or is not in a
      DataFrame-compatible format (e.g., list of dictionaries or a directly
      convertible mapping).
    """
    try:
        response = requests.get(url, timeout=5)
        response.raise_for_status()
        data = response.json()
    except requests.RequestException as exc:
        raise SystemError(f"Network error while fetching JSON from {url}: {exc}") from exc
    except ValueError as exc:
        raise ValueError(f"Invalid JSON received from {url}: {exc}") from exc

    # Validate that the JSON is directly convertible to a DataFrame in the expected form.
    if isinstance(data, dict):
        return pd.DataFrame(data)

    if isinstance(data, list):
        if not data:
            return pd.DataFrame()
        if all(isinstance(item, dict) for item in data):
            return pd.DataFrame(data)
        raise ValueError(
            "Fetched JSON data must be a list of dictionaries to be converted into a DataFrame."
        )

    raise ValueError(
        "Fetched JSON data is not in a format directly convertible to a DataFrame."
    )

