import pandas as pd
import matplotlib.pyplot as plt

def _is_uniform_from_counts(counts):
    counts = [float(c) for c in counts if pd.notna(c)]
    total = sum(counts)
    k = len(counts)

    if total <= 0:
        return True
    if k < 2:
        return False

    expected = total / k
    if expected <= 0:
        return True

    chi2 = sum((c - expected) ** 2 / expected for c in counts)
    df = k - 1
    critical = df + 2.0 * ((2.0 * df) ** 0.5)
    return chi2 <= critical


def task_func(data_dict):
    if isinstance(data_dict, pd.DataFrame):
        df = data_dict.copy()
    elif isinstance(data_dict, dict):
        df = None
        for value in data_dict.values():
            if isinstance(value, pd.DataFrame):
                df = value.copy()
                break
        if df is None:
            try:
                df = pd.DataFrame(data_dict)
            except Exception:
                df = pd.DataFrame()
    else:
        try:
