import json
import re

import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns
import pandas as pd


def task_func(json_data: str, key_path: list):
    """
    Extract numerical data from a JSON structure using a path of keys/indexes
    and return a matplotlib Figure containing a boxplot.
    """
    if not isinstance(json_data, str) or not json_data.strip():
        raise ValueError("Input JSON data is empty or invalid.")

    try:
        root = json.loads(json_data)
    except json.JSONDecodeError as exc:
        raise ValueError("Input JSON data is corrupted.") from exc

    current = root
    for key in key_path or []:
        if isinstance(current, dict):
            if key not in current:
                raise KeyError(key)
            current = current[key]
        elif isinstance(current, (list, tuple)):
            idx = key
            if isinstance(idx, str):
                if idx.strip().lstrip("-").isdigit():
                    idx = int(idx)
                else:
                    raise KeyError(key)
            elif isinstance(idx, (np.integer, int)) and not isinstance(idx, bool):
                idx = int(idx)
            else:
                raise KeyError(key)

            try:
                current = current[idx]
            except (IndexError, TypeError) as exc:
                raise KeyError(key) from exc
        else:
            raise KeyError(key)

    values = _extract_numeric_values(current)
    if not values:
        raise ValueError("No numeric data found.")

    df = pd.DataFrame({"values": values})

    fig, ax = plt.subplots(figsize=(6, 4))
    sns.boxplot(data=df, y="values", ax=ax, color="#4C72B0")
    ax.set_title("Boxplot of extracted numeric data")
    ax.set_xlabel("")
    ax.set_ylabel("Value")
    fig.tight_layout()
    return fig


def _extract_numeric_values(obj):
    if obj is None:
        return []

    if isinstance(obj, (bool, np.bool_)):
        return []

    if isinstance(obj, (int, float, np.integer, np.floating)) and not isinstance(obj, bool):
        value = float(obj)
        return [value] if np.isfinite(value) else []

    if isinstance(obj, str):
        stripped = obj.strip()
        if not stripped:
            raise ValueError("Data string is empty.")

        try:
            parsed = json.loads(stripped)
        except json.JSONDecodeError:
            tokens = re.split(r"[\s,;]+", stripped.strip("[](){}"))
            tokens = [token for token in tokens if token]

            if not tokens:
                raise ValueError("No numeric data found.")

            values = []
            for token in tokens:
                try:
                    number = float(token)
                except ValueError as exc:
                    raise ValueError("Data string is corrupted.") from exc
                if np.isfinite(number):
                    values.append(number)

            if not values:
                raise ValueError("No numeric data found.")
            return values
        else:
            return _extract_numeric_values(parsed)

    if isinstance(obj, dict):
        values = []
        for value in obj.values():
            values.extend(_extract_numeric_values(value))
        return values

    if isinstance(obj, (list, tuple, set)):
        values = []
        for item in obj:
            values.extend(_extract_numeric_values(item))
        return values

    if isinstance(obj, np.ndarray):
        values = []
        for item in obj.tolist():
            values.extend(_extract_numeric_values(item))
        return values

    if hasattr(obj, "tolist") and not isinstance(obj, pd.DataFrame):
        try:
            return _extract_numeric_values(obj.tolist())
        except Exception:
            pass

    return []
